inline constexpr size_t kDataValueCount = sizeof(kDataValues)/sizeof(kDataValues[0]);
inline const DataValueDescriptor* dataValueDescriptor(ValueId id) { for (const auto& d : kDataValues) if (d.id == id) return &d; return nullptr; }
inline bool dataValueCompatible(const DataValueDescriptor& d, const ValueMetadata& metadata) { return d.kind == DataValueKind::Digital ? metadata.type == ValueType::Bool : !(d.kind == DataValueKind::Counter && d.id >= ValueIds::Digital && d.id < ValueIds::PulseRate) || metadata.type == ValueType::UInt64; }
inline ValueId dataValueReference(const char* text, size_t length) { for (const auto& d : kDataValues) if (strlen(d.reference) == length && memcmp(d.reference, text, length) == 0) return d.id; return VALUE_INVALID; }
